// 全 metrics 一覧から "Clicked Email" を name マッチで抽出
// (Klaviyo Metrics API は name による filter 非対応)
const metricsResp = $input.first().json;
const metrics = (metricsResp && Array.isArray(metricsResp.data)) ? metricsResp.data : [];
const target = metrics.find(m => (m.attributes && m.attributes.name) === 'Clicked Email');
if (!target) {
  throw new Error('Clicked Email metric not found in Klaviyo account. Available metrics: ' + metrics.map(m => m.attributes && m.attributes.name).join(', '));
}
const since = $('BigQuery: Get MAX(event_ts)').first().json.since;
return [{ json: { metric_id: target.id, metric_name: target.attributes.name, since } }];

// Klaviyo Events 差分取得 → BigQuery raw.ec_klaviyo_events に append
// 取得対象: Clicked Email metric のイベント
// 重複: event_id 主キー (dedup view で MAX(inserted_at) 採用)
// JSON parse 注意: n8n が vnd.api+json を string で返すケースがある

function normalize(item) {
  if (item && item.json && typeof item.json.data === 'string') {
    try { return { json: JSON.parse(item.json.data) }; } catch (e) { return item; }
  }
  return item;
}

const now = new Date().toISOString();
const rows = [];

for (const rawItem of $input.all()) {
  const item = normalize(rawItem);
  const events = (item.json && Array.isArray(item.json.data)) ? item.json.data : [];
  // included から profile_id -> email lookup マップを構築
  const included = (item.json && Array.isArray(item.json.included)) ? item.json.included : [];
  const profileEmailMap = {};
  for (const inc of included) {
    if (inc.type === 'profile' && inc.attributes && inc.attributes.email) {
      profileEmailMap[inc.id] = inc.attributes.email;
    }
  }

  for (const e of events) {
    const attrs = e.attributes || {};
    const props = attrs.event_properties || {};
    const ts = attrs.datetime || attrs.timestamp || null;
    if (!ts) continue;
    // event_date: UTC → JST (+9h) → YYYY-MM-DD
    const event_date = new Date(new Date(ts).getTime() + 9 * 3600 * 1000).toISOString().substring(0, 10);
    // profile_id は relationships.profile.data.id にある
    const rel = e.relationships || {};
    const profile_id = (rel.profile && rel.profile.data && rel.profile.data.id) || attrs.profile_id || null;
    if (!profile_id) continue;
    const email = profileEmailMap[profile_id] || null;
    rows.push({
      event_id: e.id,
      metric_id: attrs.metric_id || (rel.metric && rel.metric.data && rel.metric.data.id) || null,
      metric_name: 'Clicked Email',
      profile_id: profile_id,
      email: email,
      campaign_id: props['$message'] || props.campaign_id || props.campaign || null,
      message_id: props.message_id || props['$message'] || null,
      event_ts: ts,
      event_date: event_date,
      url: props.URL || props.url || null,
      properties_json: JSON.stringify(props),
      inserted_at: now
    });
  }
}

return rows.map((json) => ({ json }));
